      },

      {
        title: "Advanced Deep Learning Solutions",
        description:
          "We leverage deep learning for advanced tasks such as image recognition, language understanding, and forecasting, enabling your business to unlock new capabilities and stay ahead in technology.",
        points: [
"Automated Object Detection",
"Speech Recognition and Analysis",
"Predictive Maintenance Models",
"Custom Neural Network Architectures",
"Advanced Visual Data Processing",
"Generative Model Development",
        ],
      },

      {
        title: "Explainable & Responsible AI",
        description:
          "We build transparent, bias-free AI models that are easy to understand and fully compliant, ensuring you can confidently scale your AI initiatives responsibly and ethically.",
        points: [
"Model Interpretability and Clarity",
"Ethical AI Frameworks",
"Accountability and Traceability",
"Fairness Audits and Assessments",
"Regulatory Compliance Assurance",
"Bias Monitoring and Prevention",
        ],
      },

    ];

    const buttonsContainer = document.getElementById("serviceButtons");
    const contentContainer = document.getElementById("serviceContent");

    function renderButtons(activeIndex = 0) {
      buttonsContainer.innerHTML = "";
      services.forEach((service, index) => {
        const isActive = index === activeIndex;
        const btnWrapper = document.createElement("div");
        btnWrapper.className = `rounded-xl ${isActive ? "pl-1 bg-gradient-to-b from-[#7C3BAF] to-[#E61C42]" : ""
          }`;

